<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Vendors</h1><p>Review applications and manage active storefronts.</p></div><a class="button button-secondary" href="<?= h(app_url('admin.users', ['role'=>'VENDOR'])) ?>">Vendor accounts</a></div>
<form class="toolbar" method="get" action="<?= h(app_url('admin.vendors')) ?>"><input type="hidden" name="r" value="admin.vendors"><div class="form-field"><label for="status">Filter by status</label><select id="status" name="status"><option value="">All vendors</option><?php foreach (['PENDING','ACTIVE','SUSPENDED','REJECTED'] as $candidate): ?><option value="<?= h($candidate) ?>"<?= $status===$candidate?' selected':'' ?>><?= h(ucfirst(strtolower($candidate))) ?></option><?php endforeach; ?></select></div><button class="button button-secondary" type="submit">Filter</button></form>
<?php if ($vendors): ?><div class="stack">
  <?php foreach ($vendors as $vendor): ?><article class="panel"><div class="spread"><div><div class="row"><span class="vendor-mark" aria-hidden="true"><?= h(mb_strtoupper(mb_substr($vendor['name'],0,2,'UTF-8'),'UTF-8')) ?></span><div><h2 class="panel-title" style="margin:0"><?= h($vendor['name']) ?></h2><div class="muted small"><?= h($vendor['owner_name']) ?> · <?= h($vendor['email']) ?><?= $vendor['owner_status'] !== 'ACTIVE' ? ' · account ' . h(strtolower($vendor['owner_status'])) : '' ?></div></div></div><p class="muted small" style="margin:10px 0 0"><?= h($vendor['pickup_location']) ?><?= $vendor['stall_label']?' · '.h($vendor['stall_label']):'' ?> · <?= (int) $vendor['food_count'] ?> foods</p><?php if ($vendor['description']): ?><p><?= h($vendor['description']) ?></p><?php endif; ?></div><div><?php $status=$vendor['status']; $badgeLabel=$status==='PENDING'?'Pending approval':status_label($status); require APP_ROOT . '/views/components/status-badge.php'; ?></div></div>
    <div class="row-wrap vendor-actions">
      <?php if ($vendor['status'] !== 'ACTIVE' && $vendor['owner_status'] !== 'ACTIVE'): ?><span class="muted small">Activate owner account before reopening</span><?php elseif ($vendor['status'] !== 'ACTIVE'): $activateLabel = $vendor['status'] === 'PENDING' ? 'Approve' : 'Activate'; ?><form method="post" action="<?= h(app_url('admin.vendor.action')) ?>" data-confirm="<?= h($activateLabel) ?> <?= h($vendor['name']) ?>?" class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $vendor['id'] ?>"><input type="hidden" name="action" value="APPROVE"><button class="button button-small" type="submit"><?= h($activateLabel) ?></button></form><?php endif; ?>
      <?php if ($vendor['status'] === 'PENDING'): ?><form method="post" action="<?= h(app_url('admin.vendor.action')) ?>" data-confirm="Reject this application?" class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $vendor['id'] ?>"><input type="hidden" name="action" value="REJECT"><button class="button button-secondary button-small" type="submit">Reject</button></form><?php endif; ?>
      <?php if ($vendor['status'] === 'ACTIVE'): ?><form method="post" action="<?= h(app_url('admin.vendor.action')) ?>" data-confirm="Suspend <?= h($vendor['name']) ?>? Students will not be able to order from this vendor." class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $vendor['id'] ?>"><input type="hidden" name="action" value="SUSPEND"><button class="button button-danger button-small" type="submit">Suspend</button></form><?php endif; ?>
    </div>
  </article><?php endforeach; ?>
</div><?php else: ?><div class="empty-state"><h2>No vendors in this view</h2><p>Vendor applications and storefronts appear here.</p></div><?php endif; ?>
